    async function tracking(body,range){const to=range?.to||new Date(Date.now()+86400000).toISOString().slice(0,10),from=range?.from||new Date(Date.now()-30*86400000).toISOString().slice(0,10);report=await api('/tracking?'+new URLSearchParams({from:from+'T00:00:00Z',to:to+'T00:00:00Z'}));body.innerHTML=card('Advertising tracking numbers',`<p>Assign a dedicated number to an advertisement or campaign. Calls and matched leads retain their first and most recent source.</p><form data-form="tracking"><div class="ph-grid">${field('from','From (UTC)',from,'date')}${field('to','Until (UTC, exclusive)',to,'date')}</div><div class="ph-actions"><button>Update report</button><button type="button" data-export>Export calls CSV</button><button type="button" data-tab="numbers">Configure tracking number</button></div></form><div class="ph-table"><table><thead><tr><th>Number / source</th><th>Campaign</th><th>Calls</th><th>Unique callers</th><th>Answered</th><th>Missed</th><th>Voicemails</th><th>New leads</th><th>Qualified</th><th>Converted</th></tr></thead><tbody>${report.sources.map(r=>`<tr><td>${esc(r.number)}<br>${esc(r.source)} · ${esc(r.medium)}</td><td>${esc(r.campaign)}<br>${esc(r.ad_id)}</td><td>${r.calls}</td><td>${r.unique_callers}</td><td>${r.answered}</td><td>${r.missed}</td><td>${r.voicemails}</td><td>${r.new_leads||0}</td><td>${r.qualified||0}</td><td>${r.converted||0}</td></tr>`).join('')||'<tr><td colspan="10">No attributed calls in this period.</td></tr>'}</tbody></table></div><h4>Lead inquiries</h4>${report.leads.map(l=>`<form data-form="lead" data-id="${esc(l.id)}" data-revision="${l.revision}"><p>${esc(l.customer_number)} · first source: ${esc(l.first_touch?.source)} · latest: ${esc(l.last_touch?.source)}</p><div class="ph-grid">${select('status','Lead outcome',l.status,[['new','New'],['qualified','Qualified'],['converted','Converted'],['spam','Spam']])}${select('project_id','Linked project',l.project_id||'',[['','No linked project'],...(report.projects||[]).map(p=>[p.id,p.label]),...(l.project_id&&!(report.projects||[]).some(p=>p.id===l.project_id)?[[l.project_id,'Currently linked project']]:[])])}</div><button>Save outcome</button></form>`).join('')}`);}
    let reputationState={},signatureInk=false;
