    const change=async event=>{const input=event.target;if(!input.dataset.greeting||!input.files?.[0])return;try{const file=input.files[0];if(file.size>4*1024*1024)throw Error('Choose a recording up to 4 MB.');const result=await api('/greetings',{name:file.name,file:await fileBase64(file)});root.querySelector(`[name="${input.dataset.greeting}"]`).value=result.greeting.id;root.querySelector(`[data-audio-label="${input.dataset.greeting}"]`).textContent=file.name;notice('Recording uploaded. Save changes to use it.');}catch(e){notice(e.message,true);}};
